-- =============================================================================
-- Six more service groups for the Services page (9 in all), each with its services.
--
-- Generated from content/services-surgical.ts, so the CMS database and the code
-- defaults hold the same entries. Run it once in the Supabase SQL editor; it is
-- safe to run again (existing slugs are left untouched).
--
-- Everything is inserted as PUBLISHED, so it shows on the website right away
-- (the publish trigger refreshes the live site). Every service is marked
-- "Temporary placeholder" for the doctor's review, and its photo is a temporary
-- stock image: edit, replace or add entries in the CMS under Services.
-- =============================================================================

begin;

-- Groups: after the existing ones, in this order
insert into public.cms_service_groups (slug, sort_order, draft, published, published_at)
select g.slug,
       (select coalesce(max(sort_order), -1) + 1 from public.cms_service_groups) + g.position,
       g.content, g.content, now()
from (values
  ('hernia-surgery', 0, $cms${"eyebrow":{"en":"Hernia surgery","ar":"جراحة الفتق"},"title":{"en":"Hernias and the abdominal wall","ar":"الفتق وجدار البطن"},"description":{"en":"Assessment and repair of hernias of the groin, the navel and previous scars, open or laparoscopic, planned around each patient's health and daily life.","ar":"تقييم وإصلاح فتق الأربية والسرة وفتق الجروح السابقة، بالجراحة المفتوحة أو بالمنظار، وفق الحالة الصحية ونمط الحياة لكل مريض."}}$cms$::jsonb),
  ('gallbladder-surgery', 1, $cms${"eyebrow":{"en":"Gallbladder","ar":"المرارة"},"title":{"en":"Gallbladder and bile duct surgery","ar":"جراحة المرارة والقنوات المرارية"},"description":{"en":"Care for gallstones and their complications, with laparoscopic surgery as the usual approach when an operation is recommended.","ar":"رعاية حصوات المرارة ومضاعفاتها، مع اعتماد الجراحة بالمنظار عادةً عندما يُوصى بالتدخل الجراحي."}}$cms$::jsonb),
  ('colorectal-surgery', 2, $cms${"eyebrow":{"en":"Colon & rectum","ar":"القولون والمستقيم"},"title":{"en":"Colorectal and anal surgery","ar":"جراحة القولون والمستقيم والشرج"},"description":{"en":"From colon and rectal tumors to common problems that people often find hard to talk about, such as hemorrhoids, fissures and fistulas — discussed openly and treated with care.","ar":"من أورام القولون والمستقيم إلى المشكلات الشائعة التي قد يتحرّج البعض من الحديث عنها، مثل البواسير والشرخ والناسور، تُناقش بصراحة وتُعالج بعناية."}}$cms$::jsonb),
  ('upper-gi-surgery', 3, $cms${"eyebrow":{"en":"Esophagus & stomach","ar":"المريء والمعدة"},"title":{"en":"Esophageal and stomach surgery","ar":"جراحة المريء والمعدة"},"description":{"en":"Surgical care for reflux and hiatal hernia, stomach tumors and the complications of ulcers, after a careful assessment of symptoms and test results.","ar":"رعاية جراحية لحالات الارتجاع وفتق الحجاب الحاجز وأورام المعدة ومضاعفات القرحة، بعد تقييم دقيق للأعراض ونتائج الفحوص."}}$cms$::jsonb),
  ('endocrine-surgery', 4, $cms${"eyebrow":{"en":"Endocrine glands","ar":"الغدد الصماء"},"title":{"en":"Thyroid, parathyroid and adrenal surgery","ar":"جراحة الغدة الدرقية والجار درقية والكظرية"},"description":{"en":"Operations on the hormone glands, planned with endocrinologists and guided by blood tests, imaging and, when needed, biopsies.","ar":"عمليات على الغدد المسؤولة عن الهرمونات، تُخطَّط مع أطباء الغدد الصماء وتسترشد بالتحاليل والأشعة والعينات عند الحاجة."}}$cms$::jsonb),
  ('surgical-oncology', 5, $cms${"eyebrow":{"en":"Surgical oncology","ar":"جراحة الأورام"},"title":{"en":"Tumor surgery and related procedures","ar":"جراحة الأورام والإجراءات المصاحبة"},"description":{"en":"Operations and procedures that are part of cancer care — from removing tumors to taking biopsies and placing ports — coordinated with the rest of the treatment plan.","ar":"عمليات وإجراءات تمثل جزءًا من رعاية الأورام، من استئصال الأورام إلى أخذ العينات وتركيب البورت، بالتنسيق مع باقي الخطة العلاجية."}}$cms$::jsonb)
) as g(slug, position, content)
on conflict (slug) do nothing;

-- Services, linked to their group and to the photo's entry in the media library
insert into public.cms_services (slug, group_id, sort_order, draft, published, published_at)
select s.slug, g.id, s.position, c.content, c.content, now()
from (values
  ('inguinal-hernia', 'hernia-surgery', 0, $cms${"title":{"en":"Inguinal hernia","ar":"الفتق الإربي"},"summary":{"en":"A bulge in the groin, assessed and repaired with a surgical mesh, often by laparoscopy.","ar":"انتفاخ في منطقة الأربية يُقيَّم ويُصلَح غالبًا باستخدام شبكة جراحية، وكثيرًا ما يكون ذلك بالمنظار."},"image":{"src":"/media/video-first-visit","alt":{"en":"A doctor measuring a patient's blood pressure","ar":"طبيب يقيس ضغط الدم لمريضة"},"position":"50% 40%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1631815588090-d4bfec5b1ccb"},"details":[{"type":"paragraph","text":{"en":"An inguinal hernia happens when tissue pushes through a weak spot in the lower abdominal wall, causing a bulge in the groin that may ache when lifting, coughing or standing for long.","ar":"يحدث الفتق الإربي عندما تبرز أنسجة من نقطة ضعف في جدار البطن السفلي، فيظهر انتفاخ في منطقة الأربية قد يؤلم عند رفع الأشياء أو السعال أو الوقوف طويلًا."}},{"type":"heading","text":{"en":"What care may include","ar":"ما قد تشمله الرعاية"}},{"type":"list","items":{"en":["Clinical examination and, when needed, an ultrasound","Repair with a surgical mesh, open or laparoscopic","Advice on returning to work, lifting and exercise","Urgent assessment if the bulge becomes painful, hard or cannot be pushed back"],"ar":["فحص سريري، وأشعة بالموجات فوق الصوتية عند الحاجة","الإصلاح باستخدام شبكة جراحية بالجراحة المفتوحة أو بالمنظار","إرشادات العودة إلى العمل ورفع الأشياء وممارسة الرياضة","تقييم عاجل إذا أصبح الانتفاخ مؤلمًا أو صلبًا أو تعذّر إرجاعه"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('umbilical-hernia', 'hernia-surgery', 1, $cms${"title":{"en":"Umbilical hernia","ar":"الفتق السري"},"summary":{"en":"Hernias at or near the navel, repaired to relieve symptoms and prevent complications.","ar":"فتق عند السرة أو بالقرب منها يُصلَح لتخفيف الأعراض والوقاية من المضاعفات."},"image":{"src":"/media/cta-consultation","alt":{"en":"A clinician measuring a patient's blood pressure during a visit","ar":"أخصائية تقيس ضغط الدم لمريضة خلال زيارتها"},"position":"40% 35%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1631815589968-fdb09a223b1e"},"details":[{"type":"paragraph","text":{"en":"Umbilical and paraumbilical hernias appear as a bulge at or around the navel. They are more common with weight gain, pregnancy or a persistent cough.","ar":"يظهر الفتق السري أو المجاور للسرة على شكل انتفاخ عند السرة أو حولها، ويزداد شيوعه مع زيادة الوزن أو الحمل أو السعال المزمن."}},{"type":"heading","text":{"en":"What care may include","ar":"ما قد تشمله الرعاية"}},{"type":"list","items":{"en":["Assessing the size of the hernia and its contents","Repair with stitches or a mesh, depending on its size","Guidance on weight and activity to reduce recurrence","Urgent review if pain, redness or vomiting appear"],"ar":["تقييم حجم الفتق ومحتواه","الإصلاح بالغرز أو بالشبكة الجراحية حسب حجمه","إرشادات بشأن الوزن والنشاط للحد من تكرار الفتق","مراجعة عاجلة عند ظهور ألم أو احمرار أو قيء"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('incisional-hernia', 'hernia-surgery', 2, $cms${"title":{"en":"Incisional hernia","ar":"الفتق الجراحي"},"summary":{"en":"A hernia at the scar of a previous operation, planned carefully because of its size and position.","ar":"فتق يظهر مكان جرح عملية سابقة، ويُخطَّط لإصلاحه بعناية وفق حجمه وموضعه."},"image":{"src":"/media/why-choose","alt":{"en":"Doctors reviewing medical images together in a bright clinic office","ar":"أطباء يراجعون صورًا طبية معًا في مكتب عيادة مضيء"},"position":"72% 40%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1666214277657-e60f05c40b04"},"details":[{"type":"paragraph","text":{"en":"An incisional hernia develops where the abdominal wall did not heal fully after surgery. Its repair is tailored to its size, the previous operation and the patient's general health.","ar":"ينشأ الفتق الجراحي حين لا يلتئم جدار البطن تمامًا بعد عملية سابقة، ويُصمَّم إصلاحه بحسب حجمه وطبيعة العملية السابقة والحالة الصحية العامة."}},{"type":"heading","text":{"en":"Planning may include","ar":"قد يشمل التخطيط"}},{"type":"list","items":{"en":["Imaging such as a CT scan to measure the defect","Preparing for surgery, including advice on weight and smoking","Mesh repair, open or laparoscopic","Follow-up to check the healing of the wound and the abdominal wall"],"ar":["فحوص تصويرية مثل الأشعة المقطعية لقياس الفتحة","التحضير للجراحة، بما في ذلك إرشادات الوزن والتدخين","الإصلاح بالشبكة الجراحية بالجراحة المفتوحة أو بالمنظار","المتابعة للتأكد من التئام الجرح وجدار البطن"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('laparoscopic-cholecystectomy', 'gallbladder-surgery', 0, $cms${"title":{"en":"Laparoscopic gallbladder removal","ar":"استئصال المرارة بالمنظار"},"summary":{"en":"The usual operation for gallstones that cause symptoms, through small incisions with a short hospital stay.","ar":"العملية المعتادة لحصوات المرارة المسببة للأعراض، عبر فتحات صغيرة مع إقامة قصيرة في المستشفى."},"image":{"src":"/media/intro-video-poster","alt":{"en":"A doctor explaining a CT scan displayed on a computer screen","ar":"طبيبة تشرح صورة أشعة مقطعية معروضة على شاشة الحاسوب"},"position":"55% 45%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1666214280557-f1b5022eb634"},"details":[{"type":"paragraph","text":{"en":"When gallstones cause pain or complications, removing the gallbladder by laparoscopy is usually recommended. Most people go home within a day or two and return to their activities gradually.","ar":"عندما تسبب حصوات المرارة ألمًا أو مضاعفات، يُوصى عادةً باستئصال المرارة بالمنظار، ويعود معظم المرضى إلى منازلهم خلال يوم أو يومين ثم يستأنفون نشاطهم تدريجيًا."}},{"type":"heading","text":{"en":"What to expect","ar":"ما يمكن توقعه"}},{"type":"list","items":{"en":["An ultrasound and blood tests before the operation","General anesthesia and a few small incisions","Pain relief and walking early after surgery","Advice on diet and activity during recovery"],"ar":["أشعة بالموجات فوق الصوتية وتحاليل دم قبل العملية","تخدير كلي وبضع فتحات صغيرة","تسكين الألم والحركة المبكرة بعد الجراحة","إرشادات حول الغذاء والنشاط خلال فترة التعافي"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('acute-cholecystitis', 'gallbladder-surgery', 1, $cms${"title":{"en":"Acute cholecystitis","ar":"التهاب المرارة الحاد"},"summary":{"en":"Sudden inflammation of the gallbladder, usually caused by a gallstone, which needs prompt assessment.","ar":"التهاب مفاجئ في المرارة يحدث غالبًا بسبب حصوة، ويحتاج إلى تقييم سريع."},"image":{"src":"/media/specialty-thoracic","alt":{"en":"A doctor examining scan images on a light box","ar":"طبيب يفحص صور الأشعة على لوح الإضاءة"},"position":"60% 35%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1581595219315-a187dd40c322"},"details":[{"type":"paragraph","text":{"en":"Acute cholecystitis causes persistent pain in the upper right abdomen, often with fever and nausea. Treatment starts in hospital, and removing the gallbladder is usually advised, early or once the inflammation settles.","ar":"يسبب التهاب المرارة الحاد ألمًا مستمرًا في أعلى البطن من الجهة اليمنى، وكثيرًا ما يصاحبه ارتفاع في الحرارة وغثيان. يبدأ العلاج في المستشفى، ويُنصح عادةً باستئصال المرارة مبكرًا أو بعد هدوء الالتهاب."}},{"type":"heading","text":{"en":"Signs that need urgent care","ar":"علامات تستدعي رعاية عاجلة"}},{"type":"list","items":{"en":["Severe pain under the right ribs lasting several hours","Fever or shivering","Yellowing of the eyes or skin","Repeated vomiting"],"ar":["ألم شديد أسفل الضلوع اليمنى يستمر عدة ساعات","ارتفاع الحرارة أو الرعشة","اصفرار العينين أو الجلد","القيء المتكرر"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('bile-duct-stones', 'gallbladder-surgery', 2, $cms${"title":{"en":"Bile duct stones","ar":"حصوات القناة المرارية"},"summary":{"en":"Stones that move into the bile duct, treated in coordination with endoscopy specialists.","ar":"حصوات تنتقل إلى القناة المرارية، وتُعالج بالتنسيق مع أطباء المناظير."},"image":{"src":"/media/page-services","alt":{"en":"Two doctors reviewing medical images on computer screens","ar":"طبيبان يراجعان صورًا طبية على شاشات الحاسوب"},"position":"70% 35%","positionMobile":"75% 30%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1666214280391-8ff5bd3c0bf0"},"details":[{"type":"paragraph","text":{"en":"Gallstones can pass into the common bile duct and block the flow of bile, causing jaundice, pain or infection. They are often removed by endoscopy (ERCP), and the gallbladder is removed afterwards.","ar":"قد تنتقل حصوات المرارة إلى القناة المرارية الرئيسية فتعيق تدفق العصارة الصفراوية، مسببةً الصفراء أو الألم أو الالتهاب. وكثيرًا ما تُستخرج بالمنظار الداخلي (ERCP)، ثم تُستأصل المرارة بعد ذلك."}},{"type":"heading","text":{"en":"What care may include","ar":"ما قد تشمله الرعاية"}},{"type":"list","items":{"en":["Blood tests and imaging such as an MRCP","Coordination with the endoscopy team","Timing the gallbladder removal once the duct is cleared","Follow-up of liver tests"],"ar":["تحاليل دم وفحوص تصويرية مثل الرنين المغناطيسي للقنوات المرارية","التنسيق مع فريق المناظير","تحديد موعد استئصال المرارة بعد تنظيف القناة","متابعة تحاليل وظائف الكبد"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('colorectal-tumors', 'colorectal-surgery', 0, $cms${"title":{"en":"Colorectal tumor surgery","ar":"جراحة أورام القولون والمستقيم"},"summary":{"en":"Surgery as part of a plan agreed with the oncology team, open or laparoscopic.","ar":"الجراحة كجزء من خطة علاجية متفق عليها مع فريق الأورام، بالجراحة المفتوحة أو بالمنظار."},"image":{"src":"/media/specialty-gastrointestinal","alt":{"en":"Two doctors discussing medical images on a monitor","ar":"طبيبان يناقشان صورًا طبية على الشاشة"},"position":"68% 40%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1666214280391-8ff5bd3c0bf0"},"details":[{"type":"paragraph","text":{"en":"Removing the affected part of the colon or rectum, with the nearby lymph nodes, is central to treating most colorectal tumors. The plan is agreed with the oncology team and may include treatment before or after the operation.","ar":"يُعد استئصال الجزء المصاب من القولون أو المستقيم مع الغدد الليمفاوية المجاورة محورًا أساسيًا في علاج معظم أورام القولون والمستقيم، وتُتفق الخطة مع فريق الأورام، وقد تشمل علاجًا قبل العملية أو بعدها."}},{"type":"heading","text":{"en":"What care may include","ar":"ما قد تشمله الرعاية"}},{"type":"list","items":{"en":["Reviewing colonoscopy, biopsy and scan results","Discussing the operation and whether a stoma may be needed","An enhanced recovery program after surgery","Follow-up with the oncology team"],"ar":["مراجعة نتائج منظار القولون والعينة والأشعة","مناقشة العملية واحتمال الحاجة إلى فتحة مؤقتة أو دائمة في البطن","برنامج التعافي السريع بعد الجراحة","المتابعة مع فريق الأورام"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('hemorrhoids', 'colorectal-surgery', 1, $cms${"title":{"en":"Hemorrhoids","ar":"البواسير"},"summary":{"en":"Treatment matched to the grade of the hemorrhoids, from diet and medicines to simple procedures and surgery.","ar":"علاج يتناسب مع درجة البواسير، من الغذاء والأدوية إلى الإجراءات البسيطة والجراحة."},"image":{"src":"/media/treatment-hormonal","alt":{"en":"Capsules beside a medicine bottle on an orange background","ar":"كبسولات دوائية بجوار عبوة دواء على خلفية برتقالية"},"position":"62% 50%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1587854692152-cbe660dbde88"},"details":[{"type":"paragraph","text":{"en":"Hemorrhoids can cause bleeding, swelling or discomfort. Many improve with fiber, fluids and medicines; persistent or advanced cases may need a procedure or surgery.","ar":"قد تسبب البواسير نزيفًا أو تورمًا أو انزعاجًا، ويتحسن كثير منها بالألياف والسوائل والأدوية، بينما قد تحتاج الحالات المستمرة أو المتقدمة إلى إجراء بسيط أو جراحة."}},{"type":"heading","text":{"en":"Good to know","ar":"معلومات مهمة"}},{"type":"list","items":{"en":["Rectal bleeding should always be examined, even when hemorrhoids are suspected","Treatment depends on the grade of the hemorrhoids and on the symptoms","Avoiding constipation helps prevent recurrence"],"ar":["ينبغي فحص أي نزيف من الشرج دائمًا، حتى عند الاشتباه في البواسير","يعتمد العلاج على درجة البواسير والأعراض","تجنّب الإمساك يساعد على منع تكرارها"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('anal-fissure', 'colorectal-surgery', 2, $cms${"title":{"en":"Anal fissure","ar":"الشرخ الشرجي"},"summary":{"en":"A small tear that causes sharp pain with bowel movements, usually treated without surgery first.","ar":"تمزق صغير يسبب ألمًا حادًا أثناء التبرز، ويُعالج عادةً دون جراحة في البداية."},"image":{"src":"/media/video-medications","alt":{"en":"A pharmacist reviewing a medicine bottle","ar":"صيدلي يراجع عبوة دواء"},"position":"50% 30%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1580281658626-ee379f3cce93"},"details":[{"type":"paragraph","text":{"en":"An anal fissure causes sharp, burning pain during and after bowel movements, sometimes with light bleeding. Most heal with stool softeners and prescribed creams; long-standing fissures may need a minor operation.","ar":"يسبب الشرخ الشرجي ألمًا حادًا وحرقانًا أثناء التبرز وبعده، وأحيانًا نزيفًا بسيطًا. يلتئم معظمه بملينات البراز والكريمات العلاجية، وقد يحتاج الشرخ المزمن إلى جراحة بسيطة."}},{"type":"heading","text":{"en":"What care may include","ar":"ما قد تشمله الرعاية"}},{"type":"list","items":{"en":["An examination to confirm the diagnosis","Diet advice, stool softeners and prescribed creams","A Botox injection or a minor operation for fissures that do not heal"],"ar":["فحص لتأكيد التشخيص","إرشادات غذائية وملينات وكريمات علاجية","حقن البوتوكس أو جراحة بسيطة للشرخ الذي لا يلتئم"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('anal-fistula', 'colorectal-surgery', 3, $cms${"title":{"en":"Anal fistula and abscess","ar":"الناسور والخراج الشرجي"},"summary":{"en":"Draining an abscess and treating a fistula while protecting continence.","ar":"تصريف الخراج وعلاج الناسور مع الحفاظ على التحكم في الإخراج."},"image":{"src":"/media/cta-consultation","alt":{"en":"A clinician measuring a patient's blood pressure during a visit","ar":"أخصائية تقيس ضغط الدم لمريضة خلال زيارتها"},"position":"40% 35%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1631815589968-fdb09a223b1e"},"details":[{"type":"paragraph","text":{"en":"An abscess near the anus causes painful swelling and fever and needs drainage. Some abscesses leave a fistula, a small tunnel that discharges, which is treated with a procedure chosen to protect the sphincter muscles.","ar":"يسبب الخراج بجوار فتحة الشرج تورمًا مؤلمًا وارتفاعًا في الحرارة، ويحتاج إلى تصريف. وقد يترك بعض الخراجات ناسورًا، وهو قناة صغيرة تفرز إفرازات، ويُعالج بإجراء يُختار للحفاظ على عضلات التحكم."}},{"type":"heading","text":{"en":"What care may include","ar":"ما قد تشمله الرعاية"}},{"type":"list","items":{"en":["Prompt drainage of an abscess","An MRI to map a complex fistula when needed","A procedure tailored to each case, sometimes in stages","Wound care and follow-up until healed"],"ar":["تصريف الخراج دون تأخير","رنين مغناطيسي لتحديد مسار الناسور المعقّد عند الحاجة","إجراء مناسب لكل حالة، وأحيانًا على مراحل","العناية بالجرح والمتابعة حتى الالتئام"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('hiatal-hernia-reflux', 'upper-gi-surgery', 0, $cms${"title":{"en":"Hiatal hernia and reflux","ar":"فتق الحجاب الحاجز والارتجاع"},"summary":{"en":"Laparoscopic repair for reflux and hiatal hernia when medicines and lifestyle changes are not enough.","ar":"إصلاح بالمنظار للارتجاع وفتق الحجاب الحاجز عندما لا تكفي الأدوية وتغيير نمط الحياة."},"image":{"src":"/media/specialty-gastrointestinal","alt":{"en":"Two doctors discussing medical images on a monitor","ar":"طبيبان يناقشان صورًا طبية على الشاشة"},"position":"68% 40%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1666214280391-8ff5bd3c0bf0"},"details":[{"type":"paragraph","text":{"en":"A hiatal hernia lets part of the stomach slide up into the chest and can make acid reflux worse. Most people are treated with medicines and lifestyle changes; surgery is considered for persistent symptoms, complications or large hernias.","ar":"يسمح فتق الحجاب الحاجز بانزلاق جزء من المعدة إلى التجويف الصدري، وقد يزيد الارتجاع الحمضي سوءًا. يُعالج معظم المرضى بالأدوية وتغيير نمط الحياة، وتُدرس الجراحة عند استمرار الأعراض أو حدوث مضاعفات أو كِبر حجم الفتق."}},{"type":"heading","text":{"en":"Before deciding on surgery","ar":"قبل اتخاذ قرار الجراحة"}},{"type":"list","items":{"en":["An upper endoscopy to examine the esophagus and stomach","Swallowing and acid tests when needed","Laparoscopic repair of the hernia with a fundoplication","Diet advice for the first weeks after the operation"],"ar":["منظار علوي لفحص المريء والمعدة","فحوص البلع والحموضة عند الحاجة","إصلاح الفتق بالمنظار مع عملية لفّ أعلى المعدة","إرشادات غذائية للأسابيع الأولى بعد العملية"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('stomach-tumors', 'upper-gi-surgery', 1, $cms${"title":{"en":"Stomach tumor surgery","ar":"جراحة أورام المعدة"},"summary":{"en":"Surgery planned with the oncology team, often combined with treatment before and after the operation.","ar":"جراحة تُخطَّط مع فريق الأورام، وكثيرًا ما تُدمج مع علاج قبل العملية وبعدها."},"image":{"src":"/media/why-choose","alt":{"en":"Doctors reviewing medical images together in a bright clinic office","ar":"أطباء يراجعون صورًا طبية معًا في مكتب عيادة مضيء"},"position":"72% 40%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1666214277657-e60f05c40b04"},"details":[{"type":"paragraph","text":{"en":"Stomach tumors are diagnosed by endoscopy and biopsy, then staged with scans. When surgery is recommended, part or all of the stomach is removed with the nearby lymph nodes, usually alongside chemotherapy.","ar":"تُشخَّص أورام المعدة بالمنظار وأخذ العينة، ثم تُحدَّد مرحلتها بالأشعة. وعندما يُوصى بالجراحة يُستأصل جزء من المعدة أو المعدة كلها مع الغدد الليمفاوية المجاورة، وغالبًا ما يصاحب ذلك علاج كيميائي."}},{"type":"heading","text":{"en":"What care may include","ar":"ما قد تشمله الرعاية"}},{"type":"list","items":{"en":["Reviewing endoscopy, pathology and staging scans","Discussion at a multidisciplinary meeting","Nutritional support before and after surgery","Long-term follow-up and advice on eating"],"ar":["مراجعة نتائج المنظار والعينة وأشعة تحديد المرحلة","مناقشة الحالة في اجتماع متعدد التخصصات","دعم غذائي قبل الجراحة وبعدها","متابعة طويلة المدى وإرشادات حول الأكل"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('peptic-ulcer-complications', 'upper-gi-surgery', 2, $cms${"title":{"en":"Ulcer complications","ar":"مضاعفات قرحة المعدة والاثني عشر"},"summary":{"en":"Urgent surgical care for a perforated or bleeding ulcer when other treatments are not enough.","ar":"رعاية جراحية عاجلة لثقب القرحة أو نزيفها عندما لا تكفي العلاجات الأخرى."},"image":{"src":"/media/video-first-visit","alt":{"en":"A doctor measuring a patient's blood pressure","ar":"طبيب يقيس ضغط الدم لمريضة"},"position":"50% 40%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1631815588090-d4bfec5b1ccb"},"details":[{"type":"paragraph","text":{"en":"Most ulcers heal with medicines. Surgery is needed when an ulcer perforates, bleeds heavily despite endoscopic treatment, or narrows the outlet of the stomach.","ar":"تلتئم معظم القرح بالأدوية، وتصبح الجراحة ضرورية عندما يحدث ثقب في القرحة، أو نزيف شديد رغم العلاج بالمنظار، أو ضيق في مخرج المعدة."}},{"type":"heading","text":{"en":"Signs that need urgent care","ar":"علامات تستدعي رعاية عاجلة"}},{"type":"list","items":{"en":["Sudden, severe abdominal pain","Vomiting blood or passing black stools","Dizziness or fainting","Repeated vomiting after meals"],"ar":["ألم مفاجئ وشديد في البطن","قيء دموي أو براز أسود","دوخة أو إغماء","قيء متكرر بعد الوجبات"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('thyroid-surgery', 'endocrine-surgery', 0, $cms${"title":{"en":"Thyroid surgery","ar":"جراحة الغدة الدرقية"},"summary":{"en":"Removal of part or all of the thyroid for nodules, goiter, overactivity or cancer.","ar":"استئصال جزء من الغدة الدرقية أو كلها في حالات العقد أو التضخم أو فرط النشاط أو الأورام."},"image":{"src":"/media/specialty-thoracic","alt":{"en":"A doctor examining scan images on a light box","ar":"طبيب يفحص صور الأشعة على لوح الإضاءة"},"position":"60% 35%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1581595219315-a187dd40c322"},"details":[{"type":"paragraph","text":{"en":"Thyroid nodules are common and most are benign. Surgery may be advised for suspicious or cancerous nodules, a large goiter that presses on the neck, or overactivity that is not controlled otherwise.","ar":"تنتشر عقد الغدة الدرقية، ومعظمها حميد. وقد يُنصح بالجراحة للعقد المشتبه بها أو الخبيثة، أو للتضخم الكبير الذي يضغط على الرقبة، أو لفرط النشاط الذي لا يُسيطر عليه بوسائل أخرى."}},{"type":"heading","text":{"en":"What care may include","ar":"ما قد تشمله الرعاية"}},{"type":"list","items":{"en":["An ultrasound and a fine-needle biopsy when needed","Checking the vocal cords and calcium levels","Removal of one lobe or of the whole gland","Thyroid hormone tablets after surgery when needed"],"ar":["أشعة بالموجات فوق الصوتية وعينة بالإبرة الدقيقة عند الحاجة","فحص الأحبال الصوتية ومستوى الكالسيوم","استئصال فص من الغدة أو الغدة كاملة","أقراص هرمون الغدة الدرقية بعد الجراحة عند الحاجة"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('parathyroid-surgery', 'endocrine-surgery', 1, $cms${"title":{"en":"Parathyroid surgery","ar":"جراحة الغدد الجار درقية"},"summary":{"en":"Removing an overactive parathyroid gland that raises the calcium in the blood.","ar":"استئصال غدة جار درقية زائدة النشاط ترفع نسبة الكالسيوم في الدم."},"image":{"src":"/media/specialty-hematologic","alt":{"en":"Blood sample tubes in a laboratory rack","ar":"أنابيب عينات دم في حامل داخل المختبر"},"position":"40% 50%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1581594693702-fbdc51b2763b"},"details":[{"type":"paragraph","text":{"en":"An overactive parathyroid gland raises the calcium in the blood, which can cause kidney stones, thinning of the bones, fatigue or low mood. Removing the affected gland is the usual cure.","ar":"يؤدي فرط نشاط الغدة الجار درقية إلى ارتفاع الكالسيوم في الدم، مما قد يسبب حصوات الكلى أو هشاشة العظام أو الإرهاق أو تقلب المزاج، ويُعد استئصال الغدة المصابة العلاج المعتاد."}},{"type":"heading","text":{"en":"What care may include","ar":"ما قد تشمله الرعاية"}},{"type":"list","items":{"en":["Blood tests for calcium and parathyroid hormone","Scans to locate the overactive gland","A focused operation through a small neck incision when possible","Calcium checks after surgery"],"ar":["تحاليل دم للكالسيوم وهرمون الغدة الجار درقية","أشعة لتحديد مكان الغدة زائدة النشاط","جراحة موضعية عبر فتحة صغيرة في الرقبة متى أمكن","متابعة مستوى الكالسيوم بعد الجراحة"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('adrenal-surgery', 'endocrine-surgery', 2, $cms${"title":{"en":"Laparoscopic adrenal surgery","ar":"استئصال الغدة الكظرية بالمنظار"},"summary":{"en":"Removal of adrenal tumors that produce excess hormones or look suspicious on scans.","ar":"استئصال أورام الغدة الكظرية التي تفرز هرمونات زائدة أو تبدو مشتبهًا بها في الأشعة."},"image":{"src":"/media/page-services","alt":{"en":"Two doctors reviewing medical images on computer screens","ar":"طبيبان يراجعان صورًا طبية على شاشات الحاسوب"},"position":"70% 35%","positionMobile":"75% 30%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1666214280391-8ff5bd3c0bf0"},"details":[{"type":"paragraph","text":{"en":"Many adrenal masses are found by chance and need no surgery. Removal, usually by laparoscopy, is advised for tumors that produce hormones, grow over time or look suspicious.","ar":"تُكتشف كثير من أورام الغدة الكظرية بالصدفة ولا تحتاج إلى جراحة، ويُنصح بالاستئصال، بالمنظار غالبًا، للأورام التي تفرز هرمونات أو تكبر مع الوقت أو تبدو مشتبهًا بها."}},{"type":"heading","text":{"en":"What care may include","ar":"ما قد تشمله الرعاية"}},{"type":"list","items":{"en":["Hormone tests on blood and urine","A CT scan or MRI to assess the mass","Preparation with medicines when the tumor produces hormones","Hormone checks during follow-up"],"ar":["تحاليل دم وبول للهرمونات","أشعة مقطعية أو رنين مغناطيسي لتقييم الورم","التحضير بالأدوية إذا كان الورم يفرز هرمونات","متابعة مستوى الهرمونات بعد الجراحة"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('breast-tumor-surgery', 'surgical-oncology', 0, $cms${"title":{"en":"Breast tumor surgery","ar":"جراحة أورام الثدي"},"summary":{"en":"Breast-conserving surgery or mastectomy, with lymph node surgery, as part of a shared plan.","ar":"جراحة تحفظ الثدي أو استئصاله، مع جراحة الغدد الليمفاوية، ضمن خطة علاجية مشتركة."},"image":{"src":"/media/specialty-breast","alt":{"en":"A patient with a radiographer during a mammogram","ar":"مريضة برفقة أخصائية الأشعة أثناء فحص الماموجرام"},"position":"58% 40%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1579154341098-e4e158cc7f55"},"details":[{"type":"paragraph","text":{"en":"Surgery for breast tumors ranges from removing the lump with a margin of healthy tissue to removing the whole breast. The choice depends on the tumor, the breast and the patient's preferences, and is made together with the oncology team.","ar":"تتراوح جراحة أورام الثدي بين استئصال الورم مع هامش من الأنسجة السليمة واستئصال الثدي بالكامل، ويعتمد الاختيار على طبيعة الورم والثدي وتفضيلات المريضة، ويُتخذ القرار بالتعاون مع فريق الأورام."}},{"type":"heading","text":{"en":"What care may include","ar":"ما قد تشمله الرعاية"}},{"type":"list","items":{"en":["Reviewing mammogram, ultrasound and biopsy results","A sentinel lymph node biopsy when appropriate","Discussing reconstruction options","Coordinating radiotherapy and medical treatment after surgery"],"ar":["مراجعة نتائج الماموجرام والموجات فوق الصوتية والعينة","أخذ عينة من الغدة الليمفاوية الحارسة عند الحاجة","مناقشة خيارات إعادة بناء الثدي","التنسيق للعلاج الإشعاعي والدوائي بعد الجراحة"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('soft-tissue-tumors', 'surgical-oncology', 1, $cms${"title":{"en":"Soft tissue lumps","ar":"أورام الأنسجة الرخوة والكتل الدهنية"},"summary":{"en":"Assessment and removal of lumps under the skin, from simple lipomas to tumors that need specialist care.","ar":"تقييم واستئصال الكتل تحت الجلد، من الأورام الدهنية البسيطة إلى الأورام التي تحتاج إلى رعاية متخصصة."},"image":{"src":"/media/video-pathology","alt":{"en":"A scientist working at a microscope in a laboratory","ar":"باحثة تعمل على المجهر في المختبر"},"position":"55% 50%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1582719471384-894fbb16e074"},"details":[{"type":"paragraph","text":{"en":"Most lumps under the skin, such as lipomas and cysts, are benign and can be removed under local anesthesia. Lumps that are large, deep, painful or growing need imaging, and sometimes a biopsy, before surgery.","ar":"معظم الكتل تحت الجلد، مثل الأورام الدهنية والأكياس، حميدة ويمكن استئصالها بالتخدير الموضعي، أما الكتل الكبيرة أو العميقة أو المؤلمة أو التي تكبر فتحتاج إلى أشعة، وأحيانًا إلى عينة، قبل الجراحة."}},{"type":"heading","text":{"en":"Signs worth checking","ar":"علامات تستحق الفحص"}},{"type":"list","items":{"en":["A lump larger than about 5 cm","A lump that is growing","A lump deep under the muscle","A lump that comes back after removal"],"ar":["كتلة يزيد حجمها على 5 سم تقريبًا","كتلة يزداد حجمها","كتلة عميقة تحت العضلة","كتلة تعود بعد استئصالها"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('lymph-node-biopsy', 'surgical-oncology', 2, $cms${"title":{"en":"Lymph node biopsy","ar":"عينة الغدد الليمفاوية"},"summary":{"en":"Removing a lymph node, or part of it, so the pathologist can make an accurate diagnosis.","ar":"استئصال غدة ليمفاوية أو جزء منها ليتمكن طبيب الأنسجة من وضع تشخيص دقيق."},"image":{"src":"/media/treatment-immunotherapy","alt":{"en":"Microscope image of cells stained blue and magenta","ar":"صورة مجهرية لخلايا ملوّنة بالأزرق والأرجواني"},"position":"50% 50%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1576086213369-97a306d36557"},"details":[{"type":"paragraph","text":{"en":"When a lymph node stays enlarged or a needle biopsy is not conclusive, removing the node gives the pathologist enough tissue to diagnose conditions such as lymphoma or the spread of a tumor.","ar":"عندما تظل الغدة الليمفاوية متضخمة أو لا تكون نتيجة العينة بالإبرة حاسمة، يتيح استئصال الغدة لطبيب الأنسجة كمية كافية من النسيج لتشخيص حالات مثل الأورام الليمفاوية أو انتشار الأورام."}},{"type":"heading","text":{"en":"What to expect","ar":"ما يمكن توقعه"}},{"type":"list","items":{"en":["Usually a short procedure, often without an overnight stay","Local or general anesthesia, depending on where the node is","Results discussed with you once the pathology report is ready"],"ar":["إجراء قصير غالبًا، وكثيرًا ما يكون دون مبيت","تخدير موضعي أو كلي حسب موضع الغدة","مناقشة النتائج معك فور صدور تقرير التحليل النسيجي"]}}],"isPlaceholder":true}$cms$::jsonb),
  ('chemotherapy-port', 'surgical-oncology', 3, $cms${"title":{"en":"Chemotherapy port insertion","ar":"تركيب بورت للعلاج الكيميائي"},"summary":{"en":"A small device under the skin that makes chemotherapy and blood tests easier and spares the veins.","ar":"جهاز صغير تحت الجلد يسهّل إعطاء العلاج الكيميائي وسحب التحاليل ويحافظ على الأوردة."},"image":{"src":"/media/treatment-chemotherapy","alt":{"en":"An infusion stand holding an intravenous bag","ar":"حامل محاليل وريدية يحمل كيس العلاج"},"position":"50% 50%","isPlaceholder":true,"credit":"Unsplash — https://images.unsplash.com/photo-1516574187841-cb9cc2ca948b"},"details":[{"type":"paragraph","text":{"en":"A port is a small reservoir placed under the skin of the chest and connected to a large vein. It allows chemotherapy, fluids and blood tests without repeated needles in the veins of the arm.","ar":"البورت خزان صغير يوضع تحت جلد الصدر ويتصل بوريد كبير، ويتيح إعطاء العلاج الكيميائي والمحاليل وسحب التحاليل دون وخز متكرر في أوردة الذراع."}},{"type":"heading","text":{"en":"Good to know","ar":"معلومات مهمة"}},{"type":"list","items":{"en":["Placed in a short procedure, usually under local anesthesia","Flushed regularly to keep it working","Fever, redness or swelling around it should be reported promptly","Removed easily once treatment is complete"],"ar":["يُركَّب في إجراء قصير، غالبًا بالتخدير الموضعي","يُغسل بانتظام للحفاظ على عمله","ينبغي الإبلاغ فورًا عن الحرارة أو الاحمرار أو التورم حوله","يُزال بسهولة بعد انتهاء العلاج"]}}],"isPlaceholder":true}$cms$::jsonb)
) as s(slug, group_slug, position, content)
join public.cms_service_groups g on g.slug = s.group_slug
left join public.cms_media m on m.bundled_src = s.content #>> '{image,src}'
cross join lateral (
  select case when m.id is null then s.content
              else jsonb_set(s.content, '{image,assetId}', to_jsonb(m.id::text)) end as content
) c
on conflict (slug) do nothing;

commit;

-- Expected: 9 groups and at least 34 services
select (select count(*) from public.cms_service_groups) as service_groups,
       (select count(*) from public.cms_services) as services;
